import React from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';
import { Quill } from 'react-quill-new';
import Dashboard from '../../src/components/Dashboard.jsx';
const owner='000000000000000000000007',key='autosave_'+owner;
const results=JSON.parse(sessionStorage.getItem('autosave-results')||'[]');
const check=(name,pass)=>{results.push({bug:'Autosave',name,pass:!!pass});sessionStorage.setItem('autosave-results',JSON.stringify(results));if(!pass)throw Error(name)};
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const wait=async predicate=>{for(let i=0;i<200;i++){if(predicate())return;await sleep(25)}throw Error('Timed out')};
const fetcher=window.fetch;window.fetch=(input,options)=>{if(new URL(input,location.href).origin!==location.origin)throw Error('External traffic blocked');return fetcher(input,options)};
localStorage.setItem('user',JSON.stringify({_id:owner,role:'user',subscription:{isActive:true}}));
if(!sessionStorage.getItem('autosave-phase'))localStorage.setItem(key,'<h2><strong>हिंदी मराठी English</strong></h2><p><br></p>');
let root=createRoot(document.getElementById('root'));
const mount=()=>root.render(<BrowserRouter><Routes><Route path="/" element={<Dashboard/>}/><Route path="*" element={<main id="away"><Link to="/">Back editor</Link></main>}/></Routes></BrowserRouter>);
const q=()=>Quill.find(document.querySelector('.ql-container'));
const remount=async()=>{root.unmount();root=createRoot(document.getElementById('root'));mount();await wait(()=>document.querySelector('.ql-editor'));await sleep(50)};
const navigateAway=()=>[...document.querySelectorAll('footer button')].find(button=>button.textContent.includes('Judgements')).click();
const report=()=>{document.body.innerHTML='<pre id="verification-result"></pre>';document.getElementById('verification-result').textContent=JSON.stringify(results)};
mount();
(async()=>{try{
 await wait(()=>document.querySelector('.ql-editor'));await sleep(50);
 if(!sessionStorage.getItem('autosave-phase')){
   check('existing formatted Unicode work restores without a blank reset',q().getText().includes('हिंदी मराठी English')&&q().getFormat(0,3).bold&&q().getFormat(0,3).header===2);
   check('actual default font is Times New Roman at 14pt, not a separate Mangal encoding',getComputedStyle(q().root).fontFamily.includes('Times New Roman')&&Math.abs(parseFloat(getComputedStyle(q().root).fontSize)-14*96/72)<0.1);
   q().insertText(q().getLength()-1,' rapid typing','user');const text=q().getText();navigateAway();
   await wait(()=>document.getElementById('away'));
   check('rapid route navigation flushes latest edit before the debounce interval',localStorage.getItem(key).includes('rapid typing'));
   document.querySelector('#away a').click();await wait(()=>document.querySelector('.ql-editor'));await sleep(50);
   check('returning from another route restores exact text and formatting',q().getText()===text&&q().getFormat(0,3).bold);
   q().insertText(q().getLength()-1,' refresh immediately','user');
   sessionStorage.setItem('autosave-expected',q().getText());sessionStorage.setItem('autosave-phase','refresh');location.reload();return;
 }
 check('real immediate refresh restores the latest edit',q().getText()===sessionStorage.getItem('autosave-expected'));
 check('refresh preserves original heading and bold formatting',q().getFormat(0,3).bold&&q().getFormat(0,3).header===2);
 const set=Storage.prototype.setItem;
 const good=localStorage.getItem(key);
 Storage.prototype.setItem=function(k,v){if(this===localStorage&&k.startsWith('autosave_'))throw new DOMException('Synthetic quota','QuotaExceededError');return set.call(this,k,v)};
 q().insertText(q().getLength()-1,' UNSAVED मराठी','user');const unsaved=q().getText();navigateAway();
 await wait(()=>document.querySelector('[role="alert"]')?.textContent.includes('NOT been saved'));
 check('failed save prevents footer navigation and shows a clear warning',location.pathname==='/'&&!document.getElementById('away'));
 check('failed save retains the last successfully saved document',localStorage.getItem(key)===good);
 check('failed save never displays a false saved status',!document.querySelector('[data-editor-autosave]')?.textContent.includes('Saved to this browser'));
 check('failed save keeps a complete owner-scoped session recovery copy',JSON.parse(sessionStorage.getItem('tnt_editor_recovery_'+owner)).html.includes('UNSAVED'));
 const create=URL.createObjectURL,anchorClick=HTMLAnchorElement.prototype.click;let recoveryBlob;
 URL.createObjectURL=blob=>{recoveryBlob=blob;return create(blob)};HTMLAnchorElement.prototype.click=function(){};
 [...document.querySelectorAll('button')].find(button=>button.textContent==='Download recovery copy').click();
 const downloaded=JSON.parse(await recoveryBlob.text());
 check('downloaded recovery contains latest owner, Unicode HTML and font metadata',downloaded.ownerId===owner&&downloaded.html.includes('UNSAVED मराठी')&&downloaded.html.includes('<strong>')&&downloaded.fontFamily==='');
 URL.createObjectURL=create;HTMLAnchorElement.prototype.click=anchorClick;
 await remount();
 check('reopen after failed writes recovers unsaved Unicode and formatting',q().getText()===unsaved&&q().getFormat(0,3).bold);
 check('recovered unsaved work stays visibly unsaved until retry succeeds',document.querySelector('[role="alert"]')?.textContent.includes('NOT been saved'));
 Storage.prototype.setItem=set;
 [...document.querySelectorAll('button')].find(button=>button.textContent==='Retry saving').click();
 await wait(()=>document.querySelector('[data-editor-autosave]')?.textContent.includes('Saved to this browser'));
 check('retry marks saved only after content actually persists',localStorage.getItem(key).includes('UNSAVED')&&sessionStorage.getItem('tnt_editor_recovery_'+owner)===null);
 q().insertText(q().getLength()-1,' pagehide','user');window.dispatchEvent(new Event('pagehide'));
 check('pagehide synchronously flushes the latest edit',localStorage.getItem(key).includes('pagehide'));
 const latest=localStorage.getItem(key),get=Storage.prototype.getItem;
 Storage.prototype.getItem=function(k){if(this===localStorage&&k===key)throw new DOMException('Synthetic read denied','SecurityError');return get.call(this,k)};
 await remount();check('initial read failure clearly pauses saving',document.querySelector('[role="alert"]')?.textContent.includes('Saving is paused'));
 q().insertText(0,'new unsaved after read failure','user');
 [...document.querySelectorAll('button')].find(button=>button.textContent==='Retry saving').click();
 Storage.prototype.getItem=get;
 check('read failure cannot overwrite unread existing saved text',localStorage.getItem(key)===latest);
}catch(error){results.push({bug:'Autosave',name:error.message,pass:false})}report()})();
